#define EXTMEM_L2_UNALLOCATE_BUFFER_CLEAR_L2_CACHE_UNALLOC_CLR_M (0x00000020U)
#define EXTMEM_L2_UNALLOCATE_BUFFER_CLEAR_L2_CACHE_UNALLOC_CLR_S (5)
#define EXTMEM_L2_UNALLOCATE_BUFFER_CLEAR_L2_CACHE_UNALLOC_CLR_V(v) (((v) << 5) & 0x00000020U)

// L1 Cache access Attribute propagation control register
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x394))
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_CC_M (0x00000001U)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_CC_S (0)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_CC_V(v) (((v) << 0) & 0x00000001U)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_WB_M (0x00000002U)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_WB_S (1)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_WB_V(v) (((v) << 1) & 0x00000002U)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_WMA_M (0x00000004U)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_WMA_S (2)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_WMA_V(v) (((v) << 2) & 0x00000004U)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_RMA_M (0x00000008U)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_RMA_S (3)
#define EXTMEM_L2_CACHE_ACCESS_ATTR_CTRL_L2_CACHE_ACCESS_FORCE_RMA_V(v) (((v) << 3) & 0x00000008U)

// Cache Tag and Data memory Object control register
#define EXTMEM_L2_CACHE_OBJECT_CTRL_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x398))
#define EXTMEM_L2_CACHE_OBJECT_CTRL_L2_CACHE_TAG_OBJECT_M (0x00000020U)
#define EXTMEM_L2_CACHE_OBJECT_CTRL_L2_CACHE_TAG_OBJECT_S (5)
#define EXTMEM_L2_CACHE_OBJECT_CTRL_L2_CACHE_TAG_OBJECT_V(v) (((v) << 5) & 0x00000020U)
#define EXTMEM_L2_CACHE_OBJECT_CTRL_L2_CACHE_MEM_OBJECT_M (0x00000800U)
#define EXTMEM_L2_CACHE_OBJECT_CTRL_L2_CACHE_MEM_OBJECT_S (11)
#define EXTMEM_L2_CACHE_OBJECT_CTRL_L2_CACHE_MEM_OBJECT_V(v) (((v) << 11) & 0x00000800U)

// Cache Tag and Data memory way register
#define EXTMEM_L2_CACHE_WAY_OBJECT_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x39C))
#define EXTMEM_L2_CACHE_WAY_OBJECT_L2_CACHE_WAY_OBJECT_M (0x00000007U)
#define EXTMEM_L2_CACHE_WAY_OBJECT_L2_CACHE_WAY_OBJECT_S (0)
#define EXTMEM_L2_CACHE_WAY_OBJECT_L2_CACHE_WAY_OBJECT_V(v) (((v) << 0) & 0x00000007U)

// Cache Vaddr register
#define EXTMEM_L2_CACHE_VADDR_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3A0))
#define EXTMEM_L2_CACHE_VADDR_L2_CACHE_VADDR_M (0xFFFFFFFFU)
#define EXTMEM_L2_CACHE_VADDR_L2_CACHE_VADDR_S (0)
#define EXTMEM_L2_CACHE_VADDR_L2_CACHE_VADDR_V(v) (((v) << 0) & 0xFFFFFFFFU)

// Cache Tag/data memory content register
#define EXTMEM_L2_CACHE_DEBUG_BUS_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3A4))
#define EXTMEM_L2_CACHE_DEBUG_BUS_L2_CACHE_DEBUG_BUS_M (0xFFFFFFFFU)
#define EXTMEM_L2_CACHE_DEBUG_BUS_L2_CACHE_DEBUG_BUS_S (0)
#define EXTMEM_L2_CACHE_DEBUG_BUS_L2_CACHE_DEBUG_BUS_V(v) (((v) << 0) & 0xFFFFFFFFU)

// USED TO SPLIT L1 CACHE AND L2 CACHE
#define EXTMEM_LEVEL_SPLIT1_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3A8))
#define EXTMEM_LEVEL_SPLIT1_LEVEL_SPLIT1_M (0xFFFFFFFFU)
#define EXTMEM_LEVEL_SPLIT1_LEVEL_SPLIT1_S (0)
#define EXTMEM_LEVEL_SPLIT1_LEVEL_SPLIT1_V(v) (((v) << 0) & 0xFFFFFFFFU)

// Clock gate control register
#define EXTMEM_CLOCK_GATE_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3AC))
#define EXTMEM_CLOCK_GATE_CLK_EN_M (0x00000001U)
#define EXTMEM_CLOCK_GATE_CLK_EN_S (0)
#define EXTMEM_CLOCK_GATE_CLK_EN_V(v) (((v) << 0) & 0x00000001U)

// Cache redundancy signal 0 register
#define EXTMEM_REDUNDANCY_SIG0_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3B0))
#define EXTMEM_REDUNDANCY_SIG0_CACHE_REDCY_SIG0_M (0xFFFFFFFFU)
#define EXTMEM_REDUNDANCY_SIG0_CACHE_REDCY_SIG0_S (0)
#define EXTMEM_REDUNDANCY_SIG0_CACHE_REDCY_SIG0_V(v) (((v) << 0) & 0xFFFFFFFFU)

// Cache redundancy signal 1 register
#define EXTMEM_REDUNDANCY_SIG1_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3B4))
#define EXTMEM_REDUNDANCY_SIG1_CACHE_REDCY_SIG1_M (0xFFFFFFFFU)
#define EXTMEM_REDUNDANCY_SIG1_CACHE_REDCY_SIG1_S (0)
#define EXTMEM_REDUNDANCY_SIG1_CACHE_REDCY_SIG1_V(v) (((v) << 0) & 0xFFFFFFFFU)

// Cache redundancy signal 2 register
#define EXTMEM_REDUNDANCY_SIG2_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3B8))
#define EXTMEM_REDUNDANCY_SIG2_CACHE_REDCY_SIG2_M (0xFFFFFFFFU)
#define EXTMEM_REDUNDANCY_SIG2_CACHE_REDCY_SIG2_S (0)
#define EXTMEM_REDUNDANCY_SIG2_CACHE_REDCY_SIG2_V(v) (((v) << 0) & 0xFFFFFFFFU)

// Cache redundancy signal 3 register
#define EXTMEM_REDUNDANCY_SIG3_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3BC))
#define EXTMEM_REDUNDANCY_SIG3_CACHE_REDCY_SIG3_M (0xFFFFFFFFU)
#define EXTMEM_REDUNDANCY_SIG3_CACHE_REDCY_SIG3_S (0)
#define EXTMEM_REDUNDANCY_SIG3_CACHE_REDCY_SIG3_V(v) (((v) << 0) & 0xFFFFFFFFU)

// Cache redundancy signal 0 register
#define EXTMEM_REDUNDANCY_SIG4_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3C0))
#define EXTMEM_REDUNDANCY_SIG4_CACHE_REDCY_SIG4_M (0x0000000FU)
#define EXTMEM_REDUNDANCY_SIG4_CACHE_REDCY_SIG4_S (0)
#define EXTMEM_REDUNDANCY_SIG4_CACHE_REDCY_SIG4_V(v) (((v) << 0) & 0x0000000FU)

// Version control register
#define EXTMEM_DATE_REG ((volatile uint32_t *)(EXTMEM_BASE + 0x3FC))
#define EXTMEM_DATE_DATE_M (0x0FFFFFFFU)
#define EXTMEM_DATE_DATE_S (0)
#define EXTMEM_DATE_DATE_V(v) (((v) << 0) & 0x0FFFFFFFU)

#endif // EXTMEM_H
